package com.amit.jobagent.application;import com.amit.jobagent.common.api.PagedResponse;import com.amit.jobagent.common.error.*;import com.amit.jobagent.profile.ActiveProfileProvider;import java.util.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service class ApplicationTrackerService{private final ApplicationTrackerRepository trackers;private final ApplicationTimelineEventRepository events;private final ActiveProfileProvider profiles;ApplicationTrackerService(ApplicationTrackerRepository t,ApplicationTimelineEventRepository e,ActiveProfileProvider p){trackers=t;events=e;profiles=p;}@Transactional(readOnly=true)PagedResponse<ApplicationTrackerResponse>list(int page,int size,boolean archived){var all=trackers.findByUserIdOrderByLastActivityAtDesc(actor()).stream().filter(x->archived== (x.archivedAt!=null)).toList();int s=Math.min(page*size,all.size()),e=Math.min(s+size,all.size());return new PagedResponse<>(all.subList(s,e).stream().map(this::map).toList(),page,size,all.size(),(all.size()+size-1)/size);}@Transactional(readOnly=true)ApplicationTrackerResponse get(UUID id){return map(owned(id));}@Transactional ApplicationTrackerResponse status(UUID id,TrackerStatusRequest req){var t=owned(id);if(t.version!=req.recordVersion())throw new ConflictException("Application changed; reload before updating status");if(!allowed(t.status,req.status()))throw new DomainValidationException("This application status transition is not permitted");var old=t.status;t.status(req.status());events.save(new ApplicationTimelineEvent(t.id,"STATUS_CHANGED",old,req.status(),"USER_REPORTED",safe(req.correctionNote()),actor()));return map(t);}@Transactional void note(UUID id,TrackerNoteRequest req){var t=owned(id);events.save(new ApplicationTimelineEvent(t.id,"USER_NOTE",null,null,"USER_REPORTED",safe(req.note()),actor()));}@Transactional ApplicationTrackerResponse archive(UUID id){var t=owned(id);t.archive();events.save(new ApplicationTimelineEvent(t.id,"TRACKER_ARCHIVED",null,null,"USER_REPORTED",null,actor()));return map(t);}@Transactional ApplicationTrackerResponse restore(UUID id){var t=owned(id);t.restore();events.save(new ApplicationTimelineEvent(t.id,"TRACKER_RESTORED",null,null,"USER_REPORTED",null,actor()));return map(t);}@Transactional(readOnly=true)List<ApplicationTimelineEvent>timeline(UUID id){return events.findByTrackerIdOrderByCreatedAtAsc(owned(id).id); }private ApplicationTracker owned(UUID id){return trackers.findById(id).filter(x->x.userId.equals(actor())).orElseThrow(()->new ResourceNotFoundException("Application was not found"));}private ApplicationTrackerResponse map(ApplicationTracker x){return new ApplicationTrackerResponse(x.id,x.handoffId,x.jobId,x.revisionId,x.status,x.submittedAt,x.lastActivityAt,x.archivedAt,x.version);}private static boolean allowed(ApplicationTrackingStatus a,ApplicationTrackingStatus b){if(a==b)return false;return switch(a){case SUBMITTED->b!=ApplicationTrackingStatus.OFFER;case ACKNOWLEDGED,UNDER_REVIEW,ASSESSMENT->b!=ApplicationTrackingStatus.OFFER||a==ApplicationTrackingStatus.ASSESSMENT;case INTERVIEW->true;case OFFER->b==ApplicationTrackingStatus.WITHDRAWN;default->false;};}private static String actor(){var a=SecurityContextHolder.getContext().getAuthentication();return a==null?"system":a.getName();}private static String safe(String s){return s==null?null:s.replaceAll("[<>]","").trim();}}
